elements.js_template:
(() => {
    const root = document.getElementById("{{ID}}");
    if (!root) return;
    const scene = root.querySelector('.cg-scene') || root;
    const layer = n => root.querySelector('.cg-l' + n);
    const motions = [];
    const textNs = [3];
    const motionOf = n => motions.find(m => m.n === n) || {};
    const on = c => c && c.type && c.type !== 'none';
    CGMotion.mount(root, {
        container: scene,
        animIn: {{{ANIMATION_IN_JSON}}}, animOut: {{{ANIMATION_OUT_JSON}}},
        text: { type: 'none' }, textOut: { type: 'none' },
        loop: {{{LOOP_JSON}}},
        onShow(tl) {
            const T = {{{TEXT_ANIM_JSON}}}, TS = {{{TEXT_ANIM_SYNC}}};
            const baseEnd = tl.duration();
            motions.forEach(m => {
                const el = layer(m.n);
                if (el && on(m.in)) tl.add(CGMotion.standardIn(el, m.in), 0);
            });
            textNs.forEach(n => {
                const el = layer(n), own = motionOf(n).text;
                const eff = own || T;
                if (!el || !on(eff)) return;
                const sub = CGMotion.applyTextEffect(el, eff);
                if (sub) tl.add(sub, own ? 0 : (TS ? Math.max(0, baseEnd - 0.1) : 0));
            });
        },
        onHide() {
        }
    });
    // Wyjście: najpierw OUT warstw (i ich efekty tekstu), potem OUT całego elementu z inspektora
    const baseHide = root.__slt_hide;
    root.__slt_hide = () => {
        const TO = {{{TEXT_ANIM_OUT_JSON}}}, TOS = {{{TEXT_ANIM_OUT_SYNC}}};
        const pre = gsap.timeline(), par = gsap.timeline();
        motions.forEach(m => {
            const el = layer(m.n);
            if (el && on(m.out)) pre.add(CGMotion.standardOut(el, m.out), 0);
        });
        textNs.forEach(n => {
            const el = layer(n), own = motionOf(n).textOut;
            const eff = own || TO;
            if (!el || !on(eff)) return;
            const sub = CGMotion.applyTextOutEffect(el, eff);
            if (!sub) return;
            if (own) pre.add(sub, 0); else par.add(sub, 0);
        });
        const base = baseHide();
        const tl = gsap.timeline();
        tl.add(pre);
        if (TOS) { tl.add(par); tl.add(base, '>-0.1'); }
        else { tl.add(base); tl.add(par, '<'); }
        return tl;
    };
})();
